export function translateUi(key, locale = DEFAULT_LOCALE, replacements = {}) {
  const template = UI_MESSAGES[locale]?.[key] || UI_MESSAGES.en[key] || key;
  return Object.entries(replacements).reduce(
    (value, [name, replacement]) => value.replaceAll(`{${name}}`, String(replacement)),
    template,
  );
}

